    12→class RuleOne(
    13→    entry: Entry, fullExtract: Boolean, option: AnalyzerOption,
    14→    spaceDictionary: SpaceDictionary?,
    15→    stopDictionary: SetDictionary?,
    16→    userDictionary: SetDictionary?,
    17→    unitDictionary: SetDictionary?,
    18→    compoundDictionary: CompoundDictionary?,
    19→    extractor: KoreanWordExtractor?
    20→) : Rule(entry, fullExtract, option) {
    21→
    22→    init {
    23→        this.spaceDictionary = spaceDictionary
    24→        this.stopDictionary = stopDictionary
    25→        this.userDictionary = userDictionary
    26→        this.unitDictionary = unitDictionary
    27→        this.compoundDictionary = compoundDictionary
    28→        this.extractor = extractor
    29→    }
    30→
    31→    override fun apply(queue: MutableList<RuleEntry>) {
    32→        val cvTmp = CharVector()
    33→        cvTmp.ignoreCase()
    34→        var eTerm: CharVector
    35→        var currentEntry: RuleEntry
    36→        var nextEntry: RuleEntry
    37→        var prevEntry: RuleEntry
    38→        Collections.sort(queue)
    39→
    40→        var qinx = 0
    41→        while (qinx < queue.size) {
    42→            currentEntry = queue[qinx]
    43→            if (isFullStringEntry(currentEntry)) {
    44→                qinx++
    45→                continue
    46→            }
    47→            if (currentEntry.length == 0) {
    48→                setDisableEntry(queue, currentEntry, qinx)
    49→                qinx++
    50→                continue
    51→            }
    52→
    53→            if (currentEntry.type == UNCATEGORIZED) {
    54→                if (!userDictionary!!.contains(currentEntry.makeTerm(null))) {
    55→                    val entry = queue.removeAt(qinx)
    56→                    Entry.split(entry, queue, qinx)
    57→                    currentEntry = queue[qinx]
    58→                } else {
    59→                    currentEntry.type = HANGUL
    60→                }
    61→            }
    62→            cvTmp.init(currentEntry.buf, currentEntry.start, currentEntry.length)
    63→
    64→            if (fullExtract) {
    65→                qinx = ruleFullExtract(queue, cvTmp, currentEntry, qinx)
    66→            }
    67→            currentEntry = queue[qinx]
    68→
    69→            if (currentEntry.type == HANGUL && currentEntry.modifiable) {
    70→                if (getType(currentEntry.buf[currentEntry.start]) == NUMBER) {
    71→                    var numInx = 1
    72→                    var numberTrans = false
    73→                    while (numInx < currentEntry.length) {
    74→                        val ch = currentEntry.buf[currentEntry.start + numInx]
    75→                        val numberChar = containsChar(AVAIL_SYMBOLS_INNUMBER, ch)
    76→                        if (numberChar) {
    77→                            numberTrans = true
    78→                        }
    79→                        if (getType(ch) != NUMBER && !numberChar) {
    80→                            break
    81→                        }
    82→                        numInx++
    83→                    }
    84→                    val unitCv = CharVector(currentEntry.buf, currentEntry.start + numInx, currentEntry.length - numInx)
    85→                    if (unitDictionary != null && unitDictionary!!.contains(unitCv)) {
    86→                        qinx = ruleUnitDict(queue, currentEntry, qinx, numInx, numberTrans, unitCv)
    87→                        qinx++
    88→                        continue
    89→                    }
    90→                } else {
    91→                    if (currentEntry.length <= 3 && currentEntry.modifiable) {
    92→                        eTerm = currentEntry.makeTerm(null)
    93→                        var joinable = false
    94→                        if (userDictionary != null && !userDictionary!!.contains(eTerm)) {
    95→                            if (isAlphaNum(eTerm)) {
    96→                                if (qinx > 0) {
    97→                                    prevEntry = queue[qinx - 1]
    98→                                    joinable = currentEntry.start == prevEntry.start + prevEntry.length && (prevEntry.type == ALPHA || prevEntry.type == NUMBER || prevEntry.type == SYMBOL)
    99→                                }
   100→                                if (!joinable && qinx + 1 < queue.size) {
   101→                                    nextEntry = queue[qinx + 1]
   102→                                    joinable = nextEntry.start == currentEntry.start + currentEntry.length && (nextEntry.type == ALPHA || nextEntry.type == NUMBER || nextEntry.type == SYMBOL)
   103→                                }
   104→                                if (joinable) {
   105→                                    queue.removeAt(qinx)
   106→                                    Entry.split(currentEntry, queue, qinx)
   107→                                }
   108→                                qinx++
   109→                                continue
   110→                            }
   111→                        }
   112→                        val eType = getTermType(eTerm)
   113→                        if (eType == ALPHA) {
   114→                            currentEntry.type = ALPHA
   115→                        } else if (eType == NUMBER) {
   116→                            logger.trace("NUMBER FOUND:{}", currentEntry)
   117→                            currentEntry.type = NUMBER
   118→                        } else if (eType == ASCII || eType == ALPHANUM) {
   119→                            currentEntry.type = MODEL_NAME
   120→                        }
   121→                    }
   122→                }
   123→            }
   124→            if (qinx + 1 < queue.size) {
   125→                prevEntry = queue[qinx + 1]
   126→                logger.trace("currentEntry0:{}/prevEntry:{} {}:{}", currentEntry, prevEntry, currentEntry.endOffset, prevEntry.startOffset)
   127→                qinx = ruleNumberEntry(queue, currentEntry, prevEntry, qinx)
   128→            }
   129→            qinx++
   130→        }
   131→        logger.trace("1st process complete / queue:{}", queue)
   132→    }
   133→
   134→    private fun ruleFullExtract(queue: MutableList<RuleEntry>, cvTmp: CharVector, currentEntry: RuleEntry, qinx: Int): Int {
   135→        var prevEntry: RuleEntry
   136→        var ctype = getType(currentEntry.buf[currentEntry.start + currentEntry.length - 1])
   137→        for (linx in 10 downTo 1) {
   138→            var passFlag = 0
   139→            val tmpBuf = currentEntry.buf
   140→            val tmpSt = currentEntry.start
   141→            var tmpEd: Int
   142→
   143→            if (queue.size > qinx + linx) {
   144→                prevEntry = queue[qinx + linx]
   145→                if (prevEntry.buf === tmpBuf && prevEntry.length > 0 && prevEntry.type != FULL_STRING) {
   146→                    tmpEd = prevEntry.start + prevEntry.length
   147→                    val tmpStCh = if (tmpSt > 0) tmpBuf[tmpSt - 1] else 0.toChar()
   148→                    val tmpEdCh = if (tmpEd < entry.lastPosition) tmpBuf[tmpEd] else 0.toChar()
   149→                    val tmpStCType = getType(tmpStCh)
   150→                    val tmpEdCType = getType(tmpEdCh)
   151→                    passFlag = ruleCombineEntry(queue, currentEntry, qinx, ctype, linx, passFlag, tmpSt, tmpEd, tmpStCh, tmpEdCh, tmpStCType, tmpEdCType)
   152→                    ctype = tmpEdCType
   153→                }
   154→            }
   155→
   156→            if (passFlag != 0) {
   157→                prevEntry = queue[qinx + linx]
   158→                cvTmp.init(currentEntry.buf, currentEntry.start, prevEntry.start + prevEntry.length - currentEntry.start)
   159→                passFlag = 0
   160→
   161→                if (spaceDictionary != null && spaceDictionary!!.containsKey(cvTmp)) {
   162→                    val currentTerm = CharVector()
   163→                    currentTerm.init(currentEntry.buf, currentEntry.start, currentEntry.length)
   164→                    val prevTerm = CharVector()
   165→                    prevTerm.init(prevEntry.buf, prevEntry.start, prevEntry.length)
   166→                    if (!unitDictionary!!.contains(currentTerm) && !unitDictionary!!.contains(prevTerm)) {
   167→                        passFlag = 1
   168→                    }
   169→                } else if (stopDictionary != null && stopDictionary!!.contains(cvTmp)) {
   170→                    passFlag = 2
   171→                } else if (containsDictionary(cvTmp)) {
   172→                    passFlag = 3
   173→                }
   174→
   175→                if (passFlag != 0) {
   176→                    Entry.merge(currentEntry, prevEntry, HANGUL)
   177→                    if (qinx + linx >= qinx) {
   178→                        queue.subList(qinx, qinx + linx + 1).clear()
   179→                    }
   180→                    return when (passFlag) {
   181→                        1 -> ruleSpaceDict(queue, cvTmp, currentEntry, qinx)
   182→                        2 -> { ruleStopDict(queue, currentEntry, qinx); qinx }
   183→                        else -> { queue.add(qinx, currentEntry); qinx }
   184→                    }
   185→                }
   186→            }
   187→        }
   188→        return qinx
   189→    }
   190→
   191→    private fun ruleUnitDict(queue: MutableList<RuleEntry>, currentEntry: RuleEntry, qinx: Int, numInx: Int, numberTrans: Boolean, unitCv: CharVector): Int {
   192→        val prevEntry = currentEntry.clone()
   193→        currentEntry.length = numInx
   194→        currentEntry.endOffset = currentEntry.startOffset + currentEntry.length
   195→        logger.trace("NUMBER FOUND:{} / {}", currentEntry, prevEntry)
   196→        if (numberTrans) {
   197→            currentEntry.type = NUMBER_TRANS
   198→        } else {
   199→            currentEntry.type = NUMBER
   200→        }
   201→        prevEntry.start += numInx
   202→        prevEntry.length -= numInx
   203→        prevEntry.type = getTermType(unitCv)
   204→        queue.add(qinx + 1, prevEntry)
   205→        return qinx + 1
   206→    }
   207→
   208→    private fun ruleCombineEntry(queue: MutableList<RuleEntry>, currentEntry: RuleEntry, qinx: Int, ctype: String?, linx: Int, passFlag: Int, tmpSt: Int, tmpEd: Int, tmpStCh: Char, tmpEdCh: Char, tmpStCType: String?, tmpEdCType: String?): Int {
   209→        var nextEntry: RuleEntry
   210→        var prevEntry: RuleEntry
   211→        if ((tmpSt == 0 || (tmpStCh.code != 0 && (tmpStCh == ' ' || tmpStCType != ctype))) &&
   212→            (tmpEd == entry.lastPosition || (tmpEdCh.code != 0 && (tmpEdCh == ' ' || tmpEdCType != ctype)))) {
   213→            var flag = 1
   214→            prevEntry = currentEntry
   215→            for (tinx in 0 until linx) {
   216→                nextEntry = queue[qinx + tinx + 1]
   217→                if (nextEntry.length == 0 || nextEntry.type == FULL_STRING || nextEntry.start != prevEntry.start + prevEntry.length) {
   218→                    flag = 0
   219→                    break
   220→                }
   221→                prevEntry = nextEntry
   222→            }
   223→            return flag
   224→        }
   225→        return passFlag
   226→    }
   227→
   228→    private fun ruleStopDict(queue: MutableList<RuleEntry>, currentEntry: RuleEntry, qinx: Int) {
   229→        currentEntry.modifiable = false
   230→        queue.add(qinx, currentEntry)
   231→    }
   232→
   233→    private fun ruleSpaceDict(queue: MutableList<RuleEntry>, cvTmp: CharVector, currentEntry: RuleEntry, qinx: Int): Int {
   234→        var prevEntry: RuleEntry
   235→        val splits = spaceDictionary!!.get(cvTmp)
   236→        var start = currentEntry.start
   237→        var startOffset = currentEntry.startOffset
   238→        for (sinx in splits!!.indices) {
   239→            val split = splits[sinx]
   240→            prevEntry = RuleEntry(currentEntry.buf, start, split.length,
   241→                startOffset, startOffset + split.length, HANGUL)
   242→            ruleStopDict(queue, prevEntry, qinx + sinx)
   243→            start += prevEntry.length
   244→            startOffset += prevEntry.length
   245→        }
   246→        return qinx + splits.size - 1
   247→    }
   248→
   249→    private fun ruleNumberEntry(queue: MutableList<RuleEntry>, currentEntry: RuleEntry, prevEntry: RuleEntry, qinx: Int): Int {
   250→        if ((currentEntry.type == NUMBER || currentEntry.type == NUMBER_TRANS)
   251→            && prevEntry.type == NUMBER && currentEntry.endOffset != prevEntry.startOffset) {
   252→            val c = currentEntry.buf[currentEntry.start + currentEntry.length]
   253→            if (logger.isTraceEnabled) {
   254→                logger.trace("c:{} / type:{} / contains:{}", c, getType(c), containsChar(AVAIL_SYMBOLS_INNUMBER, c))
   255→            }
   256→            if (getType(c) == SYMBOL && containsChar(AVAIL_SYMBOLS_INNUMBER, c)) {
   257→                queue.removeAt(qinx + 1)
   258→                currentEntry.length += 1 + prevEntry.length
   259→                currentEntry.endOffset = prevEntry.endOffset
   260→                currentEntry.type = NUMBER_TRANS
   261→                return qinx - 1
   262→            }
   263→        }
   264→        return qinx
   265→    }
   266→
   267→    private fun setDisableEntry(queue: MutableList<RuleEntry>, currentEntry: RuleEntry, qinx: Int) {
   268→        currentEntry.modifiable = false
   269→        if (qinx > 0 && qinx + 1 < queue.size) {
   270→            queue[qinx - 1].modifiable = false
   271→            queue[qinx + 1].modifiable = false
   272→        }
   273→    }
   274→}
