     9→class RuleThree(
    10→    entry: Entry, fullExtract: Boolean, option: AnalyzerOption,
    11→    unitDictionary: SetDictionary?,
    12→    unitSynonymDictionary: SynonymDictionary?
    13→) : Rule(entry, fullExtract, option) {
    14→
    15→    init {
    16→        this.unitDictionary = unitDictionary
    17→        this.unitSynonymDictionary = unitSynonymDictionary
    18→    }
    19→
    20→    override fun apply(queue: MutableList<RuleEntry>) {
    21→        var nextNextEntry: RuleEntry? = null
    22→
    23→        var qinx = 0
    24→        while (qinx < queue.size) {
    25→            val currentEntry = queue[qinx]
    26→            if (isFullStringEntry(currentEntry)) {
    27→                qinx++
    28→                continue
    29→            }
    30→
    31→            if (existNextIndex(queue, qinx)) {
    32→                val nextEntry = queue[qinx + 1]
    33→                if (isConnectedNumberEntry(currentEntry, nextEntry)) {
    34→                    nextNextEntry = getUnit(queue, nextNextEntry, qinx, currentEntry, nextEntry)
    35→                }
    36→            }
    37→            qinx++
    38→        }
    39→
    40→        logger.trace("3rd process complete / queue:{}", queue)
    41→    }
    42→
    43→    private fun getUnit(queue: MutableList<RuleEntry>, nextNextEntry: RuleEntry?, qinx: Int, currentEntry: RuleEntry, nextEntry: RuleEntry): RuleEntry? {
    44→        var result = nextNextEntry
    45→        val unitCandidate = CharVector()
    46→        unitCandidate.init(nextEntry.buf, nextEntry.start, nextEntry.length)
    47→
    48→        var findInx = 5
    49→        var foundUnit = false
    50→        while (findInx > 0) {
    51→            if (qinx + findInx < queue.size) {
    52→                val prevEntry = queue[qinx + findInx]
    53→                if (prevEntry.length == 0 || (findInx > 1 && isHangulEntry(prevEntry))) {
    54→                    findInx--
    55→                    continue
    56→                }
    57→                val unitLength = getUnitLength(nextEntry, prevEntry)
    58→                if (unitLength <= MAX_UNIT_LENGTH) {
    59→                    if (nextEntry.buf.size >= nextEntry.start + unitLength) {
    60→                        unitCandidate.init(nextEntry.buf, nextEntry.start, unitLength)
    61→                        if (findUnitDictionary(unitCandidate, getUniType(unitCandidate))) {
    62→                            foundUnit = true
    63→                            break
    64→                        }
    65→                    }
    66→                }
    67→            }
    68→            findInx--
    69→        }
    70→
    71→        if (foundUnit) {
