    74→                        qinx = removeQueue(queue, qinx)
    75→                        qinx++
    76→                        continue
    77→                    }
    78→                }
    79→
    80→                if (qinx > 0 && qinx + 1 < queue.size) {
    81→                    if (isAvailSymbol(currentEntry)) {
    82→                        // nop
    83→                    } else {
    84→                        prevEntry = queue[qinx - 1]
    85→                        nextEntry = queue[qinx + 1]
    86→                        if (isNotConnected(prevEntry, currentEntry) && isNotConnected(currentEntry, nextEntry)) {
    87→                            qinx = removeQueue(queue, qinx)
    88→                            qinx++
    89→                            continue
    90→                        }
    91→                        if (isNotModelName(nextEntry, prevEntry)) {
    92→                            qinx = removeQueue(queue, qinx)
    93→                            qinx++
    94→                            continue
    95→                        }
    96→                    }
    97→                }
    98→            }
    99→
   100→            if (isModelNameEntry(currentEntry) && currentEntry.length > 2) {
   101→                if (isEquals(getType(currentEntry.buf[currentEntry.start + currentEntry.length - 1]), SYMBOL)) {
   102→                    currentEntry.length--
   103→                    currentEntry.endOffset--
   104→                }
   105→            }
   106→
   107→            if (isNumberEntry(currentEntry) && currentEntry.length >= 5) {
   108→                currentEntry.type = MODEL_NAME
   109→            }
   110→
   111→            if (!option.useForQuery()) {
   112→                if (currentEntry.type == UNIT_ALPHA) {
   113→                    val dummy = currentEntry.clone()
   114→                    if (currentEntry.subEntry.size < 2) {
   115→                        if (currentEntry.subEntry.size == 1) {
   116→                            val number = currentEntry.subEntry.removeAt(0)
   117→                            currentEntry.start += number.length
   118→                            currentEntry.length -= number.length
   119→                            currentEntry.startOffset += number.length
   120→                            currentEntry.type = ALPHA
   121→                            addQueue(queue, qinx, number)
   122→                        } else {
   123→                            currentEntry.type = ALPHANUM
   124→                        }
   125→                        currentEntry.synonym = null
   126→                        addQueue(queue, qinx, dummy)
   127→                    }
   128→                }
   129→            }
   130→            qinx++
   131→        }
   132→
   133→        syncQueueWithEntry(queue)
   134→
   135→        if (queue.size > 1 && isFullStringEntry(queue[0].also { currentEntry = it })
   136→            && (queue[1].also { prevEntry = it }).startOffset == currentEntry.startOffset && prevEntry.endOffset == currentEntry.endOffset) {
   137→            combineSynonym(queue, prevEntry, currentEntry)
   138→        }
   139→
   140→        logger.trace("5th process complete / queue:{}", queue)
   141→    }
   142→
   143→    private fun combineSynonym(queue: MutableList<RuleEntry>, prevEntry: RuleEntry, currentEntry: RuleEntry) {
   144→        if (currentEntry.synonym != null && currentEntry.synonym!!.isNotEmpty() &&
   145→            prevEntry.synonym != null && prevEntry.synonym!!.isNotEmpty()) {
   146→            val len = prevEntry.synonym!!.size
   147→            prevEntry.synonym = Arrays.copyOf(prevEntry.synonym, len + currentEntry.synonym!!.size)
   148→            System.arraycopy(currentEntry.synonym!!, 0, prevEntry.synonym!!, len, currentEntry.synonym!!.size)
   149→        } else if (currentEntry.synonym != null && currentEntry.synonym!!.isNotEmpty()) {
   150→            prevEntry.synonym = currentEntry.synonym
   151→        }
   152→        queue.removeAt(0)
   153→    }
   154→
   155→    private fun syncQueueWithEntry(queue: MutableList<RuleEntry>) {
   156→        var currentEntry: RuleEntry
   157→        for (ruleEntry in queue) {
   158→            currentEntry = ruleEntry
   159→            if (isFullStringEntry(currentEntry)) {
   160→                continue
   161→            }
   162→            if (currentEntry.subEntry != null && currentEntry.subEntry.size > 0) {
   163→                logger.trace("subEntry:{}", currentEntry.subEntry)
   164→                currentEntry.modifiable = true
   165→            } else {
   166→                currentEntry.subEntry = ArrayList()
   167→                currentEntry.modifiable = false
   168→            }
   169→
   170→            val token = currentEntry.makeTerm(null)
   171→            if (!option.useForQuery() && existCompoundDict(token)) {
   172→                val compounds = compoundDictionary!!.get(token)
   173→                for (word in compounds!!) {
   174→                    val cv = CharVector.valueOf(word)
   175→                    val entry = RuleEntry(cv.array(), cv.offset(), cv.length(), currentEntry.startOffset, currentEntry.endOffset, COMPOUND)
   176→                    currentEntry.subEntry.add(entry)
   177→                }
   178→                Collections.sort(currentEntry.subEntry)
   179→                currentEntry.type = COMPOUND
   180→            }
   181→        }
   182→    }
   183→
   184→    private fun existCompoundDict(token: CharVector): Boolean {
   185→        return compoundDictionary != null && compoundDictionary!!.containsKey(token)
   186→    }
   187→
   188→    private fun isNotModelName(nextEntry: RuleEntry, prevEntry: RuleEntry): Boolean {
   189→        return isNotEntryType(prevEntry, ALPHA, NUMBER, ALPHANUM, NUMBER_TRANS, SYMBOL)
   190→                || isNotEntryType(nextEntry, ALPHA, NUMBER, ALPHANUM, NUMBER_TRANS, SYMBOL)
   191→    }
   192→
   193→    private fun isHeadIndex(queue: MutableList<RuleEntry>, qinx: Int): Boolean {
   194→        return qinx == 0 && qinx + 1 < queue.size
   195→    }
   196→
   197→    private fun isAvailSymbol(currentEntry: RuleEntry): Boolean {
   198→        return currentEntry.length == 1 && containsChar(AVAIL_SYMBOLS_STANDALONE, currentEntry.buf[currentEntry.start])
   199→    }
   200→
   201→    private fun isNotAvailSymbol(currentEntry: RuleEntry): Boolean {
   202→        return isSymbolEntry(currentEntry) && !containsChar(AVAIL_SYMBOLS, currentEntry.buf[currentEntry.start])
   203→    }
   204→
   205→    private fun removeQueue(queue: MutableList<RuleEntry>, qinx: Int): Int {
   206→        queue.removeAt(qinx)
   207→        return qinx - 1
   208→    }
   209→
   210→    private fun addQueue(queue: MutableList<RuleEntry>, qinx: Int, entry: RuleEntry): Int {
   211→        queue.add(qinx, entry)
   212→        return qinx + 1
   213→    }
   214→}
