     4→import org.apache.logging.log4j.LogManager
     5→
     6→class RuleEntry(
     7→    var buf: CharArray,
     8→    var start: Int,
     9→    var length: Int,
    10→    var startOffset: Int,
    11→    var endOffset: Int,
    12→    var type: String?
    13→) : Comparable<RuleEntry> {
    14→
    15→    var modifiable: Boolean = true
    16→    var synonym: Array<CharSequence>? = null
    17→    var subEntry: MutableList<RuleEntry> = ArrayList()
    18→
    19→    fun makeTerm(cv: CharVector?): CharVector {
    20→        return makeTerm(cv, start, length)
    21→    }
    22→
    23→    fun makeTerm(cv: CharVector?, start: Int, length: Int): CharVector {
    24→        val result = cv ?: CharVector()
    25→        result.init(buf, start, length)
    26→        return result
    27→    }
    28→
    29→    public override fun clone(): RuleEntry {
    30→        val entry = RuleEntry(buf, start, length, startOffset, endOffset, type)
    31→        entry.synonym = synonym
    32→        entry.subEntry = subEntry
    33→        return entry
    34→    }
    35→
    36→    override fun toString(): String {
    37→        var str = ""
    38→        if (buf != null) {
    39→            try {
    40→                str = "\"${String(buf, start, length)}\""
    41→            } catch (ex: Exception) {
    42→                str = "\"${String(buf)}\" [$start:$length]"
    43→                logger.debug("EE:{}", ex.message)
    44→            }
    45→        }
    46→        str += " / $type / $modifiable ($start~${start + length}/$startOffset~$endOffset)"
    47→        if (subEntry != null) {
    48→            str += "[${subEntry.size}]"
    49→        }
    50→        val syn = synonym
    51→        if (syn != null) {
    52→            str += "[${syn.size}]"
    53→        }
    54→        return str
    55→    }
    56→
    57→    override fun compareTo(other: RuleEntry): Int {
    58→        var ret = this.startOffset - other.startOffset
    59→        if (ret == 0) {
    60→            ret = if (this.startOffset == this.endOffset) {
    61→                -1
    62→            } else if (other.startOffset == other.endOffset) {
    63→                1
    64→            } else {
    65→                other.endOffset - this.endOffset
    66→            }
    67→        }
    68→        return ret
    69→    }
    70→
    71→    companion object {
    72→        private val logger = LogManager.getLogger(RuleEntry::class.java)
    73→    }
    74→}
