    10→public class RuleTwo extends Rule {
    11→
    12→    public RuleTwo(Entry entry, boolean fullExtract, AnalyzerOption option) {
    13→        super(entry, fullExtract, option);
    14→    }
    15→
    16→    @Override
    17→    public void apply(List<RuleEntry> queue) {
    18→        // 2차 가공, 변경타입을 생성한다 ( NUMBER_TRANS 등 )
    19→        for (int qinx = 0; qinx < queue.size(); qinx++) {
    20→            RuleEntry currentEntry = queue.get(qinx);
    21→
    22→            if (isFullStringEntry(currentEntry)) {
    23→                continue;
    24→            }
    25→
    26→            // 다다음 인덱스가 존재할 경우
    27→            if (existNextNextIndex(queue, qinx)) {
    28→                RuleEntry nextEntry = queue.get(qinx + 1);
    29→                RuleEntry nextNextEntry = queue.get(qinx + 2);
    30→
    31→                // 변경 가능한 대상일 경우
    32→                if (isChangeableNumber(currentEntry, nextEntry, nextNextEntry)) {
    33→                    RuleEntry cloneEntry = currentEntry.clone();
    34→                    currentEntry.length += nextEntry.length + nextNextEntry.length;
    35→                    currentEntry.endOffset = currentEntry.startOffset + currentEntry.length;
    36→
    37→                    // 숫자 패턴여부 체크해서 NUMBER_TRANS 타입으로 변환
    38→                    if (isNumberPattern(currentEntry)) {
    39→                        qinx = changeTransNumber(queue, qinx, currentEntry);
    40→                        continue;
    41→                    } else {
    42→                        restoreEntry(currentEntry, cloneEntry);
    43→                    }
    44→                }
    45→            }
    46→
    47→            // 다음 인덱스가 존재할 경우
    48→            if (existNextIndex(queue, qinx)) {
    49→                qinx = modifyEtc(queue, qinx, currentEntry);
    50→            }
    51→        }
    52→        logger.trace("2nd process complete / queue:{}", queue);
    53→    }
    54→
    55→    private int modifyEtc(List<RuleEntry> queue, int qinx, RuleEntry currentEntry) {
    56→        // ALPHA, NUMBER, JAPAN, CHINA 변경
    57→        RuleEntry nextEntry = queue.get(qinx + 1);
    58→        if (isConnectEntry(currentEntry, nextEntry)) {
    59→            qinx = ruleAlterType(queue, qinx, currentEntry, nextEntry);
    60→        }
    61→        return qinx;
    62→    }
    63→
    64→    private int ruleAlterType(List<RuleEntry> queue, int qinx, RuleEntry currentEntry, RuleEntry nextEntry) {
    65→        if (isAlphaEntry(currentEntry) && isAlphaEntry(nextEntry)) {
    66→            setEntryType(queue, qinx, ALPHA);
    67→        } else if (isNumberEntry(currentEntry) && isNumberEntry(nextEntry)) {
    68→            setEntryType(queue, qinx, NUMBER);
    69→        } else if (isJapanOrChina(currentEntry, nextEntry)) {
    70→            // 외래어 포용성이 높은 문자로 이동 ( 중국어 처럼 보인다 하더라도 일본어가 섞인 블럭이면 일본어 )
    71→            qinx = setEntryTypeJapanese(queue, qinx, currentEntry, nextEntry);
    72→        }
    73→        return qinx;
    74→    }
    75→
    76→    private int setEntryTypeJapanese(List<RuleEntry> queue, int qinx, RuleEntry currentEntry, RuleEntry nextEntry) {
    77→        currentEntry.length += nextEntry.length;
    78→        currentEntry.endOffset = nextEntry.endOffset;
    79→        currentEntry.type = JAPANESE;
    80→        queue.remove(qinx + 1);
    81→        qinx--;
    82→        return qinx;
    83→    }
    84→
    85→    private boolean isJapanOrChina(RuleEntry currentEntry, RuleEntry nextEntry) {
    86→        return isJapanese(currentEntry) && isJapanese(nextEntry)
    87→                || (isChinese(currentEntry) && isChinese(nextEntry))
    88→                || (isJapanese(currentEntry) && isChinese(nextEntry));
    89→    }
    90→
    91→    private void setEntryType(List<RuleEntry> queue, int qinx, String type) {
    92→        RuleEntry currentEntry;
    93→        currentEntry = Entry.mergeQueueQuery(qinx + 2, 2, queue, null);
    94→        if (currentEntry != null) {
    95→            currentEntry.type = type;
    96→        }
    97→    }
    98→
    99→    private boolean isNumberPattern(RuleEntry currentEntry) {
   100→        return PTN_NUMBER.matcher(currentEntry.makeTerm(null)).find();
   101→    }
   102→
   103→    private boolean isConnectEntry(RuleEntry currentEntry, RuleEntry nextEntry) {
   104→        return isConnected(currentEntry, nextEntry) && currentEntry.length > 0 && nextEntry.length > 0;
   105→    }
   106→
   107→    private void restoreEntry(RuleEntry currentEntry, RuleEntry cloneEntry) {
   108→        currentEntry.length = cloneEntry.length;
   109→        currentEntry.endOffset = cloneEntry.endOffset;
   110→    }
   111→
   112→    private int changeTransNumber(List<RuleEntry> queue, int qinx, RuleEntry currentEntry) {
   113→        currentEntry.type = NUMBER_TRANS;
   114→        queue.remove(qinx + 2);
   115→        queue.remove(qinx + 1);
   116→        qinx--;
   117→        return qinx;
   118→    }
   119→
   120→    private boolean isChangeableNumber(RuleEntry currentEntry, RuleEntry nextEntry, RuleEntry nextNextEntry) {
   121→        return isEntryType(currentEntry, NUMBER, NUMBER_TRANS)
   122→                && isSymbolEntry(nextEntry) && nextEntry.length == 1
   123→                && isNumberEntry(nextNextEntry)
   124→                && isConnected(currentEntry, nextEntry)
   125→                && isConnected(nextEntry, nextNextEntry)
   126→                && isAvailSymbolChar(nextEntry.buf[nextEntry.start]);
   127→    }
   128→
   129→    private boolean isAvailSymbolChar(char c) {
   130→        return containsChar(AVAIL_SYMBOLS_INNUMBER, c);
   131→    }
   132→}
