    12→public class RuleFour extends Rule {
    13→    public RuleFour(Entry entry, boolean fullExtract, AnalyzerOption option, SetDictionary unitDictionary) {
    14→        super(entry, fullExtract, option);
    15→        this.unitDictionary = unitDictionary;
    16→    }
    17→
    18→    @Override
    19→    public void apply(List<RuleEntry> queue) {
    20→        // 엔트리의 연속 사항을 기록하는 객체
    21→        ContinuousOption remainOption = new ContinuousOption();
    22→
    23→        for (int qinx = 0; qinx < queue.size(); qinx++) {
    24→            RuleEntry currentEntry = initEntry(queue, remainOption, qinx);
    25→
    26→            // 전/후 엔트리를 비교하여, 모델명을 이룰 수 있는 엔트리 탐색
    27→            if (remainOption.isAlphaNum || isSymbolEntry(currentEntry) || isUnitAlphaEntry(currentEntry) || isUnitEntry(currentEntry)) {
    28→                if (qinx == 0) {
    29→                    // NOP
    30→                } else if (qinx < queue.size()) {
    31→                    RuleEntry prevEntry = queue.get(qinx - 1);
    32→
    33→                    // 분리어로 분리된 경우
    34→                    if (currentEntry.length == 0 || prevEntry.length == 0) {
    35→                        breakContinuous(remainOption, remainOption.typeContinuous);
    36→                    } else if (isConnected(prevEntry, currentEntry)  && (
    37→                            (
    38→                                // 특수문자는 연달아 나올수 없다.
    39→                                isNotSymbol(currentEntry) && ((remainOption.isAlphaNumPrev) || isUnitAlphaEntry(prevEntry) || (isSymbolEntry(prevEntry) && remainOption.typeContinuous > 0))
    40→                                // 이 단계에서 UNIT은 한글 단위밖에 없으므로 모델명으로 처리하면 안됨
    41→                                && !(isAlphaEntry(prevEntry) && isUnitEntry(currentEntry))
    42→                            ) ||
    43→                            (
    44→                                isSymbolEntry(currentEntry) && (remainOption.isAlphaNumPrev || (isUnitAlphaEntry(prevEntry) && remainOption.typeContinuous > 0)) && currentEntry.length == 1 && containsChar(AVAIL_SYMBOLS_CONNECTOR, currentEntry.buf[currentEntry.start])
    45→                            ) ||
    46→                                // 영단위는 - 를 만나면 일단 이어질수 있는것으로 본다.
    47→                            (
    48→                                isUnitAlphaEntry(currentEntry) && prevEntry.length == 1 && prevEntry.buf[prevEntry.start] == AVAIL_SYMBOLS[0]
    49→                            )
    50→                              ||
    51→                            (
    52→                                isSymbolEntry(currentEntry) && (remainOption.isAlphaNumPrev || (isUnitAlphaEntry(prevEntry) && remainOption.typeContinuous >= 0)) && currentEntry.length == 1 && currentEntry.buf[currentEntry.start] == AVAIL_SYMBOLS[0]
    53→                            )
    54→                              ||
    55→                                // 색인 시 영단위는 / 를 만나면 일단 이어질수 있는것으로 본다.
    56→                            (
    57→                                !option.useForQuery() && isUnitAlphaEntry(currentEntry) && prevEntry.length == 1 && prevEntry.buf[prevEntry.start] == AVAIL_SYMBOLS[2]
    58→                            )
    59→                              ||
    60→                            (
    61→                                !option.useForQuery() && isSymbolEntry(currentEntry) && (remainOption.isAlphaNumPrev || (isUnitAlphaEntry(prevEntry) && remainOption.typeContinuous >= 0)) && currentEntry.length == 1 && currentEntry.buf[currentEntry.start] == AVAIL_SYMBOLS[2])
    62→                            )
    63→                    ) {
    64→                        remainOption.typeContinuous++;
    65→                        remainOption.isContinue = true;
    66→                    } else {
    67→                        // 문자가 끊겼으므로 이전까지의 연결을 머징해주고 클리어한다.
    68→                        breakContinuous(remainOption, remainOption.typeContinuous);
    69→                    }
    70→                }
    71→            } else {
    72→                breakContinuous(remainOption, remainOption.typeContinuous);
    73→            }
    74→            if (logger.isTraceEnabled()) {
    75→                logger.trace("qinx:{} / type:{} / typePrev:{} / typeCont:{} / continue:{} / e0:{} / char:[{}]:{}", qinx, remainOption.type, remainOption.typePrev, remainOption.typeContinuous, remainOption.isContinue, currentEntry, currentEntry.buf[currentEntry.start], containsChar(AVAIL_SYMBOLS_INNUMBER, currentEntry.buf[currentEntry.start]));
    76→            }
    77→
    78→            // 병합되기 직전의 처리로 병합을 취소할 수 있는. 예외로직을 기재한다.
    79→            if (remainOption.type == UNIT_ALPHA && remainOption.typePrev == UNIT_ALPHA) {
    80→                if(option.useForQuery()){
    81→                    RuleEntry prevEntry = queue.get(qinx - 1);
    82→                    if (isConnected(prevEntry, currentEntry)) {
    83→                        logger.trace("model name cancel 1");
    84→                        cancelModelName(queue, remainOption, qinx, currentEntry);
    85→                    } else {
    86→                        logger.trace("model name break !");
    87→                        remainOption.isContinue = false;
    88→                        remainOption.typePrev = null;
    89→                    }
    90→                } else {
    91→                    logger.trace("model name break !");
    92→                    remainOption.isContinue = false;
    93→                    remainOption.typePrev = null;
    94→                }
    95→            } else if (remainOption.type == SYMBOL && currentEntry.length == 1) {
    96→                qinx = ruleSymbolEntry(queue, remainOption, qinx, currentEntry);
    97→            } else if (remainOption.type == UNIT_ALPHA) {
    98→                ruleUnitAlphaEntry(queue, remainOption, qinx, currentEntry);
    99→            }
   100→            if (remainOption.isContinue) {
   101→                logger.trace("continue..");
   102→                continue;
   103→            }
   104→
   105→            // 모델명 조합에 사용된 모든 텀들을 재조합하여 가지고 있는다.
   106→            if (remainOption.typeContinuousMerge > 0) {
   107→                qinx = combineUsedModelNameTerm(queue, remainOption, qinx, currentEntry);
   108→            }
   109→            remainOption.typeContinuousMerge = 0;
   110→        } // for
   111→        if (remainOption.typeContinuous > 0 && remainOption.typeContinuousMerge == 0) {
   112→            remainOption.typeContinuousMerge = remainOption.typeContinuous;
   113→        }
   114→        if (remainOption.typeContinuousMerge > 0) {
   115→            ruleRemainTerm(queue, remainOption);
   116→        }
   117→        logger.trace("4th process complete / queue:{}", queue);
   118→    }
