   372→    private void cancelModelName(ContinuousOption remainOption, RuleEntry prevEntry, RuleEntry nextEntry) {
   373→        if (remainOption.isContinue && remainOption.typeContinuous != 0 && remainOption.typeContinuousMerge == 0) {
   374→            prevEntry.modifiable = false;
   375→            nextEntry.modifiable = false;
   376→            breakContinuous(remainOption, remainOption.typeContinuous);
   377→        }
   378→        // +이후까지 본 상황 이므로 다음 인덱스는 1개의 오차가 생긴다.
   379→        remainOption.overIndex = 1;
