   388→    private RuleEntry initEntry(List<RuleEntry> queue, ContinuousOption remainOption, int qinx) {
   389→        remainOption.typePrev = remainOption.type;
   390→        RuleEntry currentEntry = queue.get(qinx);
   391→        // 단어사전에 있는 영문단어는 한글로 인식되므로
   392→        // 영문단어인 경우 ALPHA 타입으로 전환
   393→        // 차후 동일타입 결합에 의해 영문뭉치는
   394→        // 결합단어로도 추출됨 (AdditionalTerm)
   395→        // FULL_STRING 은 타입전환을 하지 않는다
   396→        CharVector cv = currentEntry.makeTerm(null);
   397→        if (currentEntry.type != FULL_STRING && getType(cv.charAt(0)) == ALPHA && (option.useForQuery() || (!option.useForQuery() && currentEntry.type != UNIT))) {
   398→            if (getTermType(cv) == ALPHA) {
   399→                currentEntry.type = ALPHA;
   400→            }
   401→        }
   402→        remainOption.type = currentEntry.type;
   403→        remainOption.isContinue = true;
   404→        remainOption.typeContinuousMerge = 0;
   405→        remainOption.overIndex = 0;
   406→
   407→        if (currentEntry.type == FULL_STRING) {
   408→            remainOption.typeContinuousMerge = remainOption.typeContinuous;
   409→            remainOption.typeContinuous = 0;
   410→        }
   411→
   412→        if (logger.isTraceEnabled()) {
   413→            logger.trace("qinx:{} / type:{} / typePrev:{} / typeCont:{} / e0:{} / char:[{}]:{}", qinx, remainOption.type, remainOption.typePrev, remainOption.typeContinuous, currentEntry, currentEntry.buf[currentEntry.start], containsChar(AVAIL_SYMBOLS_INNUMBER, currentEntry.buf[currentEntry.start]));
   414→        }
   415→
   416→        remainOption.isAlphaNumPrev = remainOption.isAlphaNum;
   417→        remainOption.isAlphaNum = currentEntry.type == ALPHA || currentEntry.type == NUMBER || currentEntry.type == NUMBER_TRANS;
   418→        return currentEntry;
   419→    }
