   110→            }
   111→
   112→            // 5자리 이상의 독립적인 숫자는 모델명으로 리턴.
   113→            if (isNumberEntry(currentEntry)  && currentEntry.length >= 5) {
   114→                currentEntry.type = MODEL_NAME;
   115→            }
   116→
   117→            // 색인시 단위명 규칙에서 단위명을 추가로 뽑아준다
   118→            if(!option.useForQuery()){
   119→                if (currentEntry.type == UNIT_ALPHA) {
   120→                    RuleEntry dummy = currentEntry.clone();
   121→
   122→                    // 숫자+단위 한 텀씩 결합할때만..
   123→                    if (currentEntry != null && currentEntry.subEntry.size() < 2) {
   124→                        if (currentEntry != null && currentEntry.subEntry.size() == 1) {
   125→                            RuleEntry number = currentEntry.subEntry.remove(0);
   126→                            currentEntry.start += number.length;
   127→                            currentEntry.length -= number.length;
   128→                            currentEntry.startOffset += number.length;
   129→                            currentEntry.type = ALPHA;
   130→                            addQueue(queue, qinx, number);
   131→                        } else {
   132→                            currentEntry.type = ALPHANUM;
   133→                        }
   134→                        currentEntry.synonym = null;
   135→                        addQueue(queue, qinx, dummy);
   136→                    }
   137→                }
   138→            }
   139→        }
   140→
   141→        // 큐의 추가삭제는 없으므로 동시 처리 해 준다.
   142→        syncQueueWithEntry(queue);
   143→
   144→        // FULL-TERM 과 나머지 1개 TERM 이 같은 경우
   145→        if (queue.size() > 1 && isFullStringEntry(currentEntry = queue.get(0))
   146→            && (prevEntry = queue.get(1)).startOffset == currentEntry.startOffset && prevEntry.endOffset == currentEntry.endOffset) {
   147→            // 동의어 합치기
   148→            combineSynonym(queue, prevEntry, currentEntry);
   149→        }
   150→
   151→        logger.trace("5th process complete / queue:{}", queue);
   152→    }
   153→
   154→    private void combineSynonym(List<RuleEntry> queue, RuleEntry prevEntry, RuleEntry currentEntry) {
   155→        if (currentEntry.synonym != null && currentEntry.synonym.length > 0 &&
   156→                prevEntry.synonym != null && prevEntry.synonym.length > 0) {
   157→            int len = prevEntry.synonym.length;
   158→            prevEntry.synonym = Arrays.copyOf(prevEntry.synonym, len + currentEntry.synonym.length);
   159→            System.arraycopy(currentEntry.synonym, 0, prevEntry.synonym, len, currentEntry.synonym.length);
   160→        } else if(currentEntry.synonym != null && currentEntry.synonym.length > 0) {
   161→            prevEntry.synonym = currentEntry.synonym;
   162→        } else {
   163→            // NOP
   164→        }
   165→        queue.remove(0);
   166→    }
   167→
   168→    private void syncQueueWithEntry(List<RuleEntry> queue) {
   169→        RuleEntry currentEntry;
   170→        for (RuleEntry ruleEntry : queue) {
   171→            // modifiable 을 특별 용도로 사용한다.
   172→            currentEntry = ruleEntry;
   173→
   174→            if (isFullStringEntry(currentEntry)) {
   175→                continue;
   176→            }
   177→            if (currentEntry.subEntry != null && currentEntry.subEntry.size() > 0) {
   178→                logger.trace("subEntry:{}", currentEntry.subEntry);
   179→                currentEntry.modifiable = true;
   180→            } else {
   181→                currentEntry.subEntry = null;
   182→                currentEntry.modifiable = false;
   183→            }
   184→
   185→            CharVector token = currentEntry.makeTerm(null);
   186→            if (!option.useForQuery() && existCompoundDict(token)) {
   187→                CharSequence[] compounds = compoundDictionary.get(token);
   188→                for (CharSequence word : compounds) {
   189→                    CharVector cv = CharVector.valueOf(word);
   190→                    RuleEntry entry = new RuleEntry(cv.array(), cv.offset(), cv.length(), currentEntry.startOffset, currentEntry.endOffset, COMPOUND);
   191→                    if (currentEntry.subEntry == null) {
   192→                        currentEntry.subEntry = new ArrayList<>();
   193→                    }
   194→                    currentEntry.subEntry.add(entry);
   195→                }
   196→                if (currentEntry.subEntry != null) {
   197→                    Collections.sort(currentEntry.subEntry);
   198→                }
   199→                currentEntry.type = COMPOUND;
   200→            }
   201→        }
   202→    }
   203→
   204→    private boolean existCompoundDict(CharVector token) {
   205→        return compoundDictionary != null && compoundDictionary.containsKey(token);
   206→    }
   207→
   208→    private boolean isNotModelName(RuleEntry nextEntry, RuleEntry prevEntry) {
   209→        return isNotEntryType(prevEntry, ALPHA, NUMBER, ALPHANUM, NUMBER_TRANS, SYMBOL)
   210→                || isNotEntryType(nextEntry, ALPHA, NUMBER, ALPHANUM, NUMBER_TRANS, SYMBOL);
   211→    }
   212→
   213→    private boolean isHeadIndex(List<RuleEntry> queue, int qinx) {
   214→        return qinx == 0 && qinx + 1 < queue.size();
   215→    }
   216→
   217→    private boolean isAvailSymbol(RuleEntry currentEntry) {
   218→        return currentEntry.length == 1 && containsChar(AVAIL_SYMBOLS_STANDALONE, currentEntry.buf[currentEntry.start]);
   219→    }
   220→
   221→    private boolean isNotAvailSymbol(RuleEntry currentEntry) {
   222→        // TODO:특수문자가 한꺼번에 많이 들어온 경우 허용되는 특수문자만 가린다.
   223→        return isSymbolEntry(currentEntry) && !containsChar(AVAIL_SYMBOLS, currentEntry.buf[currentEntry.start]);
   224→    }
   225→
   226→    private int removeQueue(List<RuleEntry> queue, int qinx) {
   227→        queue.remove(qinx);
   228→        qinx--;
   229→        return qinx;
   230→    }
   231→
   232→    private int addQueue(List<RuleEntry> queue, int qinx, RuleEntry entry) {
   233→        queue.add(qinx, entry);
   234→        qinx++;
   235→        return qinx;
   236→    }
   237→}

